    compromised_ids = compromised_ids or set()
    detected_ids = detected_ids or set()

    net_viz = Network(height="650px", width="100%", bgcolor="#1e1e1e",
                       font_color="white", directed=False)
    
    # Repulsion physics pulls the nodes into a much tighter, shorter-lined cluster
    net_viz.repulsion(node_distance=130, spring_length=50, central_gravity=0.2, spring_strength=0.1)

    for n in nodes:
        style = DEVICE_STYLE.get(n["type"], {"image": DEVICE_STYLE["scada_server"]["image"]})
        border = "rgba(0,0,0,0)"
        if n["id"] in compromised_ids:
            border = "#ff3b30"   # red ring = currently under attack
        elif n["id"] in detected_ids:
            border = "#34c759"   # green ring = attack detected here

        net_viz.add_node(
            n["id"],
            label=n["label"],
            shape="image",
            shapeProperties={"useBorderWithImage": True},
            image=style["image"],
            color={"border": border, "background": "rgba(0,0,0,0)"},
            borderWidth=5 if n["id"] in (compromised_ids | detected_ids) else 0,
            title=n["label"],
            size=40,
        )

    for e in edges:
        if e["type"] == "power_line":
            kwargs = {"color": "#f5a623", "width": 3, "title": "Power Line (electrical layer)"}
        elif e["type"] == "comm":
            proto = e.get("protocol", "TCP/IP")
            kwargs = {"color": "#4a90d9", "dashes": True, "title": f"Comm Link ({proto})"}
        else:
            kwargs = {"color": "#666666", "width": 1}
        net_viz.add_edge(e["from"], e["to"], **kwargs)

    html = net_viz.generate_html()
    legend = """
    <div style="position: absolute; bottom: 20px; left: 20px; background-color: rgba(30, 30, 30, 0.9); color: white; padding: 15px; border-radius: 8px; font-family: sans-serif; font-size: 13px; border: 1px solid #444; z-index: 1000; box-shadow: 0 4px 6px rgba(0,0,0,0.3);">
        <h4 style="margin: 0 0 12px 0; font-size: 15px; color: #ddd; border-bottom: 1px solid #555; padding-bottom: 5px;">Topology Legend</h4>
        <div style="display: flex; align-items: center; margin-bottom: 8px;">
            <div style="width: 25px; height: 3px; background-color: #f5a623; margin-right: 10px;"></div> Power Line (Physical)
        </div>
        <div style="display: flex; align-items: center; margin-bottom: 12px;">
            <div style="width: 25px; border-bottom: 2px dashed #4a90d9; margin-right: 10px;"></div> Comm Link (IT/OT)
        </div>
        <div style="display: flex; align-items: center; margin-bottom: 8px;">
            <div style="width: 14px; height: 14px; border: 3px solid #ff3b30; border-radius: 50%; margin-right: 10px; margin-left: 5px; box-sizing: border-box;"></div> Node Compromised
        </div>
        <div style="display: flex; align-items: center;">
            <div style="width: 14px; height: 14px; border: 3px solid #34c759; border-radius: 50%; margin-right: 10px; margin-left: 5px; box-sizing: border-box;"></div> Attack Detected (IDS)
        </div>
    </div>
    """
    return html.replace('</body>', legend + '\n</body>')